$env=GreenPortalDatabase::env();$pdo=GreenPortalDatabase::connect($env,'gatlas_dbp','GPT');$user=(int)$pdo->query('SELECT codusuario FROM usuarios WHERE ativo=1 ORDER BY codusuario LIMIT 1')->fetchColumn();if($user<=0)throw new RuntimeException('Atlas sem usuário ativo.');$key='TEST_AGENDA_SERVICE_186_'.date('YmdHis');$agenda=new AgendaService($pdo,new TaskService($pdo));$rec=$agenda->createRecurring(['chave_idempotencia'=>$key,'codusuario_criador'=>$user,'codusuario_responsavel'=>$user,'titulo'=>'Teste AgendaService 186','descricao'=>'Evento temporário de homologação.','frequencia'=>'DIARIA','intervalo'=>1,'proxima_execucao'=>date('Y-m-d H:i:s',time()-60)]);$worker=escapeshellarg(PHP_BINARY).' '.escapeshellarg(__DIR__.'/task-worker.php').' --database=gatlas_dbp --limit=20';$out=[];$exit=0;exec($worker,$out,$exit);$q=$pdo->prepare('SELECT codeventoagenda FROM agenda_eventos WHERE codrecorrencia=:rec AND chave_idempotencia LIKE :chave');$q->execute(['rec'=>$rec,'chave'=>'AGENDA_RECORRENCIA:'.$rec.':%']);$event=(int)$q->fetchColumn();$execs=(int)$pdo->query('SELECT COUNT(*) FROM agenda_execucoes WHERE codrecorrencia='.$rec)->fetchColumn();$task=(int)$pdo->query("SELECT codtarefa FROM green_tasks WHERE origem_entidade='agenda_eventos' AND origem_id='".$event."' ORDER BY codtarefa DESC LIMIT 1")->fetchColumn();$alerts=0;if($task>0){$a=$pdo->prepare('SELECT COUNT(*) FROM alertas WHERE link=:link');$a->execute(['link'=>'TASK:'.$task]);$alerts=(int)$a->fetchColumn();}$pdo->prepare('DELETE FROM alertas WHERE link=:link')->execute(['link'=>'TASK:'.$task]);if($task>0){$pdo->prepare('DELETE FROM green_task_history WHERE codtarefa=:id')->execute(['id'=>$task]);$pdo->prepare('DELETE FROM green_tasks WHERE codtarefa=:id')->execute(['id'=>$task]);}$pdo->prepare('DELETE FROM agenda_execucoes WHERE codrecorrencia=:id')->execute(['id'=>$rec]);if($event>0)$pdo->prepare('DELETE FROM agenda_eventos WHERE codeventoagenda=:id')->execute(['id'=>$event]);$pdo->prepare('DELETE FROM agenda_recorrencias WHERE codrecorrencia=:id')->execute(['id'=>$rec]);echo json_encode(['ok'=>$exit===0&&$event>0&&$execs===1&&$alerts===1,'worker_exit'=>$exit,'recorrencia'=>$rec,'evento_materializado'=>$event,'execucoes'=>$execs,'alertas'=>$alerts,'limpeza'=>true],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT).PHP_EOL;
